// Golden vectors of schema version 0.2 (ADR-0016 §8.1). The 0.2 envelope and
// projection are the reviewed 0.1 vectors with the version token replaced: the
// bump changes the version and nothing else while the catalog stays the same.
// They are reviewed constants, no expectation in this file is generated by the
// encoder under test, and the digest is recomputed from the literal with the
// standard library.
const (
	goldenV02Envelope   = `{"schema_version":"0.2","subject":{"cluster_alias":"cluster-a","namespace":"payments","kind":"Pod","name":"payments-api-7f4d","uid":"pod-uid-1","owner_chain":"deployments/payments-api"},"images":[{"container_class":"init","container_name":"setup","requested_image":null,"raw_image_id":"registry.example/setup@sha256:bbb","normalized_digest":null,"platform":{"os":null,"architecture":null,"status":"unknown"},"observed_at":null},{"container_class":"regular","container_name":"api","requested_image":"registry.example/app:release","raw_image_id":"registry.example/app@sha256:aaa","normalized_digest":"sha256:aaa","platform":{"os":"linux","architecture":"amd64","status":"known"},"observed_at":"2026-09-23T12:00:00Z"}],"evidence":[{"type":"container_status.image_id","source":"sanitized-pods.json","source_hash":"sha256:ccc","locator":"items[3].status.containerStatuses[0].imageID","value":"sha256:aaa","value_hash":"sha256:bbb","observed_at":"2026-09-23T12:00:00Z","confidence":"observed","scope":{"subject_uid":"pod-uid-1","container_name":"api"},"warnings":[{"code":"redaction_applied","class":"informational","message":"policy \"default\" applied \\ to values"}]},{"type":"pod_spec.containers[].image","source":"sanitized-pods.json","source_hash":"sha256:ccc","locator":"items[3].spec.containers[0].image","value":null,"value_hash":null,"observed_at":"2026-09-23T12:00:00Z","confidence":"unavailable","scope":{"subject_uid":"pod-uid-1","container_name":"api"},"warnings":[]}],"observed_container_classes":["ephemeral","init","regular"],"provenance":{"collector_version":"0.1","parser_version":"kubectl-v1.2","ruleset":{"path":"rules/","hash":"sha256:ddd","version":"2026-09"},"argv_sanitized":["get","pods","-o","json","--namespace","payments"],"inputs":[{"path":"sanitized-pods.json","hash":"sha256:eee"}],"api_scope":{"namespaces":["payments"],"verbs":["get","list"],"resources":["pods"]},"started_at":"2026-09-23T12:00:00Z","ended_at":"2026-09-23T12:30:00Z","budget":{"wall_clock":"5m","requests":1000,"objects":5000,"bytes":52428800},"coverage":{"method":"container_observation","termination":"finished","rows":null},"completeness":"complete","consistency":"point-observation","redaction_policy":"default-v1","warnings":[{"code":"redaction_applied","class":"informational","message":"policy \"default\" applied \\ to values"},{"code":"tool_failure","class":"informational","message":"collector retried the request"}],"errors":[]}}`
	goldenV02Projection = `{"schema_version":"0.2","subject":{"cluster_alias":"cluster-a","namespace":"payments","kind":"Pod","name":"payments-api-7f4d","uid":"pod-uid-1","owner_chain":"deployments/payments-api"},"images":[{"container_class":"init","container_name":"setup","requested_image":null,"raw_image_id":"registry.example/setup@sha256:bbb","normalized_digest":null,"platform":{"os":null,"architecture":null,"status":"unknown"},"observed_at":null},{"container_class":"regular","container_name":"api","requested_image":"registry.example/app:release","raw_image_id":"registry.example/app@sha256:aaa","normalized_digest":"sha256:aaa","platform":{"os":"linux","architecture":"amd64","status":"known"},"observed_at":"2026-09-23T12:00:00Z"}],"evidence":[{"type":"container_status.image_id","source":"sanitized-pods.json","source_hash":"sha256:ccc","locator":"items[3].status.containerStatuses[0].imageID","value":"sha256:aaa","value_hash":"sha256:bbb","observed_at":"2026-09-23T12:00:00Z","confidence":"observed","scope":{"subject_uid":"pod-uid-1","container_name":"api"},"warnings":[{"code":"redaction_applied","class":"informational","message":"policy \"default\" applied \\ to values"}]},{"type":"pod_spec.containers[].image","source":"sanitized-pods.json","source_hash":"sha256:ccc","locator":"items[3].spec.containers[0].image","value":null,"value_hash":null,"observed_at":"2026-09-23T12:00:00Z","confidence":"unavailable","scope":{"subject_uid":"pod-uid-1","container_name":"api"},"warnings":[]}],"observed_container_classes":["ephemeral","init","regular"],"provenance":{"ruleset":{"path":"rules/","hash":"sha256:ddd"},"inputs":[{"path":"sanitized-pods.json","hash":"sha256:eee"}],"api_scope":{"namespaces":["payments"],"verbs":["get","list"],"resources":["pods"]},"coverage":{"method":"container_observation","termination":"finished","rows":null},"completeness":"complete","consistency":"point-observation","redaction_policy":"default-v1","warnings":[{"code":"redaction_applied","class":"informational","message":"policy \"default\" applied \\ to values"},{"code":"tool_failure","class":"informational","message":"collector retried the request"}],"errors":[]}}`
	goldenV02Hash       = `sha256:73f0f3907fe66fcb0cbad369279028231aff2dcc04c81e7af29e8b43418d45b0`
)

// testGoldenV02Bundle is the reviewed data of the 0.1 golden vector, read and
// written as 0.2. The pair proves the version changes the bundle hash and
// nothing else.
func testGoldenV02Bundle(t *testing.T) contract.Bundle {
	t.Helper()
	bundle := testGoldenBundle(t)
	bundle.SchemaVersion = "0.2"
	return bundle
}

// The catalog of ADR-0016 §4.1, transcribed independently in this file:
// 59 names = 14 mapping + 15 artifact + 21 vendor common + 2 vulnerable_build
// + 3 fixed_build + 4 code_excluded_build. The transcription is the oracle of
// the vectors; it is never derived from the encoder under test.
var (
	v02MappingNames = []string{
		"method", "coverage", "vulnerability_id", "scanner_package_type",
		"scanner_package_name", "scanner_package_id", "vendor", "product_id",
		"product_release", "os", "architecture", "component_id", "package_name",
		"package_arch",
	}
	v02ArtifactNames = []string{
		"method", "coverage", "artifact_digest", "digest_kind", "vendor",
		"product_id", "product_release", "os", "architecture", "component_id",
		"package_name", "package_arch", "epoch", "version", "package_release",
	}
	v02VendorCommonNames = []string{
		"method", "coverage", "vulnerability_id", "advisory_id",
		"advisory_revision", "vendor", "product_id", "product_release", "os",
		"architecture", "component_id", "package_name", "package_arch", "epoch",
		"version", "package_release", "source_status_vocabulary",
		"source_status_value", "proof_kind", "basis_id", "basis_locator",
	}
	v02VulnerableNames = []string{"vulnerable_code_id", "applicability"}
	v02FixedNames      = []string{"fixed_code_id", "fix_id", "fix_membership"}
	v02ExcludedNames   = []string{"excluded_code_id", "build_id", "exclusion", "exclusion_coverage"}
)

func v02Prefixed(prefix string, names []string) []string {
	prefixed := make([]string, 0, len(names))
	for _, name := range names {
		prefixed = append(prefixed, prefix+name)
	}
	return prefixed
}

func v02CatalogNames() []string {
	var names []string
	names = append(names, v02Prefixed("product_v1.mapping.", v02MappingNames)...)
	names = append(names, v02Prefixed("product_v1.artifact.", v02ArtifactNames)...)
	names = append(names, v02Prefixed("product_v1.vendor.", v02VendorCommonNames)...)
	names = append(names, v02Prefixed("product_v1.vendor.", v02VulnerableNames)...)
	names = append(names, v02Prefixed("product_v1.vendor.", v02FixedNames)...)
	names = append(names, v02Prefixed("product_v1.vendor.", v02ExcludedNames)...)
	return names
}

func v02VendorWith(extra []string) []string {
	combined := append(append([]string{}, v02VendorCommonNames...), extra...)
	return v02Prefixed("product_v1.vendor.", combined)
}

func reverseNamesV02(names []string) {
	for left, right := 0, len(names)-1; left < right; left, right = left+1, right-1 {
		names[left], names[right] = names[right], names[left]
	}
}

// v02ProductBundle replaces the evidence of the reviewed vector with one item
// per product name, in the declared order. The items share every other field,
// so the canonical order of the envelope is decided by the type.
func v02ProductBundle(t *testing.T, itemTypes []string) contract.Bundle {
	t.Helper()
	bundle := testGoldenV02Bundle(t)
	subject := testSubject()
	bundle.Evidence = make([]contract.EvidenceItem, 0, len(itemTypes))
	for _, itemType := range itemTypes {
		item := testItem(t, testScope(subject, testContainer()), contract.ProvenanceObserved, nil)
		item.Type = itemType
		bundle.Evidence = append(bundle.Evidence, item)
	}
	return bundle
}

func TestCanonicalV02GoldenVectors(t *testing.T) {
	t.Run("frozen bytes", func(t *testing.T) {
		bundle := testGoldenV02Bundle(t)
		if encoded := string(canonicalEnvelope(t, bundle)); encoded != goldenV02Envelope {
			t.Fatalf("the canonical 0.2 envelope changed.\nwant:\n%s\ngot:\n%s", goldenV02Envelope, encoded)
		}
		projection := string(canonicalProjection(t, bundle))
		if projection != goldenV02Projection {
			t.Fatalf("the 0.2 hash projection changed.\nwant:\n%s\ngot:\n%s", goldenV02Projection, projection)
		}
		hash := hashOf(t, bundle)
		if hash != goldenV02Hash {
			t.Fatalf("the canonical 0.2 hash changed.\nwant:\n%s\ngot:\n%s", goldenV02Hash, hash)
		}
		digest := sha256.Sum256([]byte(goldenV02Projection))
		if expected := "sha256:" + hex.EncodeToString(digest[:]); expected != goldenV02Hash {
			t.Fatalf("the 0.2 golden hash is not the SHA-256 of the golden projection: %s", expected)
		}
	})

	t.Run("the version token is the only difference", func(t *testing.T) {
		legacy := string(canonicalEnvelope(t, testGoldenBundle(t)))
		bumped := string(canonicalEnvelope(t, testGoldenV02Bundle(t)))
		swapped := strings.Replace(legacy, `"schema_version":"0.1"`, `"schema_version":"0.2"`, 1)
		if swapped != bumped {
			t.Fatal("the 0.2 vector must differ from the 0.1 vector only in schema_version")
		}
	})

	t.Run("three variants cover the 59 names", func(t *testing.T) {
		cases := []struct {
			name      string
			types     []string
			exclusive []string
		}{
			{"mapping", v02Prefixed("product_v1.mapping.", v02MappingNames), nil},
			{"artifact", v02Prefixed("product_v1.artifact.", v02ArtifactNames), nil},
			{"vulnerable_build", v02VendorWith(v02VulnerableNames), v02Prefixed("product_v1.vendor.", v02VulnerableNames)},
			{"fixed_build", v02VendorWith(v02FixedNames), v02Prefixed("product_v1.vendor.", v02FixedNames)},
			{"code_excluded_build", v02VendorWith(v02ExcludedNames), v02Prefixed("product_v1.vendor.", v02ExcludedNames)},
		}
		seen := map[string]int{}
		for _, testCase := range cases {
			declared := append([]string{}, testCase.types...)
			reverseNamesV02(declared)
			bundle := v02ProductBundle(t, declared)
			if _, err := CanonicalJSON(bundle); err != nil {
				t.Fatalf("case %s did not canonicalize: %v", testCase.name, err)
			}
			for _, itemType := range testCase.types {
				seen[itemType]++
			}
			for _, exclusive := range testCase.exclusive {
				if seen[exclusive] > 1 {
					t.Fatalf("the exclusive name %s also appears outside %s", exclusive, testCase.name)
				}
			}
		}
		want := v02CatalogNames()
		if len(want) != 59 {
			t.Fatalf("the transcribed catalog has %d names, want 59", len(want))
		}
		if len(seen) != len(want) {
			t.Fatalf("the vectors cover %d distinct names, want %d", len(seen), len(want))
		}
		for _, name := range want {
			if seen[name] == 0 {
				t.Fatalf("the vectors do not cover %s", name)
			}
		}
		common := v02Prefixed("product_v1.vendor.", v02VendorCommonNames)
		for _, name := range common {
			if seen[name] != 3 {
				t.Fatalf("the shared vendor name %s appears in %d vendor cases, want 3", name, seen[name])
			}
		}
	})

	t.Run("duplicates and canonical order", func(t *testing.T) {
		types := v02Prefixed("product_v1.mapping.", v02MappingNames)
		declared := append([]string{}, types...)
		reverseNamesV02(declared)
		declared = append(declared, types[0])
		bundle := v02ProductBundle(t, declared)
		encoded := canonicalEnvelope(t, bundle)
		var decoded struct {
			Evidence []struct {
				Type string `json:"type"`
			} `json:"evidence"`
		}
		if err := json.Unmarshal(encoded, &decoded); err != nil {
			t.Fatalf("unmarshal envelope: %v", err)
		}
		got := make([]string, 0, len(decoded.Evidence))
		for _, item := range decoded.Evidence {
			got = append(got, item.Type)
		}
		want := append(append([]string{}, types...), types[0])
		sort.Strings(want)
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("the evidence array is not the canonical order with duplicates preserved.\nwant:\n%v\ngot:\n%v", want, got)
		}
	})

	t.Run("escapes and unnormalized Unicode", func(t *testing.T) {
		bundle := v02ProductBundle(t, []string{"product_v1.vendor.basis_locator"})
		value := "policy \"default\" applied \\ to cafe\u0301 and a < b & c > d"
		digest := sha256.Sum256([]byte(value))
		hash := contract.ValueHash("sha256:" + hex.EncodeToString(digest[:]))
		bundle.Evidence[0].Value = &value
		bundle.Evidence[0].ValueHash = &hash
		encoded := string(canonicalEnvelope(t, bundle))
		if !strings.Contains(encoded, `\"default\"`) || !strings.Contains(encoded, `\\`) {
			t.Fatalf("quotes and backslashes are not escaped as JSON requires: %s", encoded)
		}
		if !strings.Contains(encoded, "cafe\u0301") {
			t.Fatal("the decomposed Unicode bytes were not preserved")
		}
		if strings.Contains(encoded, "caf\u00e9") {
			t.Fatal("the encoder normalized Unicode")
		}
		if !strings.Contains(encoded, "a < b & c > d") {
			t.Fatal("the encoder escaped HTML characters")
		}
	})
}

// TestV02HashCoverageAndVersion follows ADR-0016 §1 and §8.1: the version is
// covered by the bundle hash, the value hashes survive the bump, and type,
// source, locator and provenance claims stay covered.
func TestV02HashCoverageAndVersion(t *testing.T) {
	base := testGoldenV02Bundle(t)
	baseHash := hashOf(t, base)

	t.Run("version changes the bundle hash and not the value hashes", func(t *testing.T) {
		legacy := testGoldenBundle(t)
		if hashOf(t, legacy) == baseHash {
			t.Fatal("the same data under 0.1 and 0.2 must not share a bundle digest")
		}
		if len(legacy.Evidence) != len(base.Evidence) {
			t.Fatalf("the reviewed pair must carry the same evidence: %d vs %d", len(legacy.Evidence), len(base.Evidence))
		}
		// The reviewed vector carries one item with a value and one unavailable
		// item without one; the pair must agree on the values it does carry.
		checked := 0
		for index := range base.Evidence {
			left, right := legacy.Evidence[index], base.Evidence[index]
			if left.Value == nil || right.Value == nil {
				if left.ValueHash != nil || right.ValueHash != nil {
					t.Fatalf("evidence[%d] carries a hash without a value", index)
				}
				continue
			}
			if left.ValueHash == nil || right.ValueHash == nil {
				t.Fatalf("evidence[%d] lost its value_hash", index)
			}
			if *left.ValueHash != *right.ValueHash {
				t.Fatalf("evidence[%d] changed its value_hash across versions", index)
			}
			if *left.Value != *right.Value {
				t.Fatalf("evidence[%d] changed its value across versions", index)
			}
			checked++
		}
		if checked == 0 {
			t.Fatal("the fixture must carry at least one value to compare across versions")
		}
	})

	covered := map[string]func(*contract.Bundle){
		"type":   func(b *contract.Bundle) { b.Evidence[1].Type = "container_status.image_id.renamed" },
		"source": func(b *contract.Bundle) { b.Evidence[1].Source = "sanitized-pods-2.json" },
		"locator": func(b *contract.Bundle) {
			b.Evidence[1].Locator = contract.SourceLocator("items[4].status.containerStatuses[0].imageID")
		},
		"value with an intact value_hash": func(b *contract.Bundle) {
			changed := "sha256:zzz"
			b.Evidence[1].Value = &changed
		},
		"value_hash": func(b *contract.Bundle) {
			changed := contract.ValueHash("sha256:999")
			b.Evidence[1].ValueHash = &changed
		},
		"image identity": func(b *contract.Bundle) { b.Images[0].ContainerName = contract.ContainerName("api-2") },
		"provenance claim": func(b *contract.Bundle) {
			b.Provenance.Warnings = append(b.Provenance.Warnings, contract.Warning{
				Code: "partial_observation", Class: contract.WarningInformational, Message: "one namespace was skipped",
			})
		},
		"ruleset hash": func(b *contract.Bundle) { b.Provenance.Ruleset.Hash = contract.SourceHash("sha256:999") },
	}
	for name, mutate := range covered {
		t.Run("covered/"+name, func(t *testing.T) {
			bundle := testGoldenV02Bundle(t)
			mutate(&bundle)
			if hashOf(t, bundle) == baseHash {
				t.Fatalf("mutating %s kept the digest, which §1(a) forbids", name)
			}
		})
	}
}

// TestV02WireContractPreserved walks the ten limits ADR-0016 §5 keeps for the
// minor bump: structure and keys, arrays and null, enums, projection,
// exclusions, hash preimages, canonicalization, completeness, warnings and the
// artifact rule that the digest covers the projection and not the envelope.
func TestV02WireContractPreserved(t *testing.T) {
	bundle := testGoldenV02Bundle(t)
	envelope := string(canonicalEnvelope(t, bundle))
	projection := string(canonicalProjection(t, bundle))

	t.Run("keys and order", func(t *testing.T) {
		if !strings.HasPrefix(envelope, `{"schema_version":"0.2","subject":{`) {
			t.Fatalf("the envelope does not start with the frozen key order: %s", envelope[:60])
		}
		previous := -1
		for _, key := range []string{`"subject":{`, `"images":[`, `"evidence":[`, `"observed_container_classes":[`, `"provenance":{`} {
			index := strings.Index(envelope, key)
			if index < 0 {
				t.Fatalf("the envelope lost %s", key)
			}
			if index < previous {
				t.Fatalf("the top-level key %s is out of order", key)
			}
			previous = index
		}
	})

	t.Run("arrays and null", func(t *testing.T) {
		for _, kept := range []string{`"value":null`, `"value_hash":null`, `"warnings":[]`, `"rows":null`, `"requested_image":null`} {
			if !strings.Contains(envelope, kept) {
				t.Fatalf("the envelope lost the frozen null/array form %s", kept)
			}
		}
		nulled := testGoldenV02Bundle(t)
		nulled.Provenance.Errors = nil
		if _, err := CanonicalJSON(nulled); err == nil {
			t.Fatal("a nil collection was collapsed into [] instead of being rejected")
		}
	})

	t.Run("enums unchanged", func(t *testing.T) {
		consistency := testGoldenV02Bundle(t)
		consistency.Provenance.Consistency = contract.Consistency("eventual")
		if _, err := CanonicalJSON(consistency); err == nil {
			t.Fatal("a value outside the closed Consistency enum was accepted in 0.2")
		}
		classes := testGoldenV02Bundle(t)
		classes.ObservedContainerClasses = append(classes.ObservedContainerClasses, contract.ContainerClass("sidecar"))
		if _, err := CanonicalJSON(classes); err == nil {
			t.Fatal("a container class outside the closed enum was accepted in 0.2")
		}
	})

	t.Run("projection", func(t *testing.T) {
		start := strings.Index(projection, `"provenance":{`)
		if start < 0 {
			t.Fatal("the projection lost its provenance section")
		}
		tail := projection[start:]
		previous := -1
		for _, key := range []string{`"ruleset":`, `"inputs":`, `"api_scope":`, `"coverage":`, `"completeness":`, `"consistency":`, `"redaction_policy":`, `"warnings":`, `"errors":`} {
			index := strings.Index(tail, key)
			if index < 0 {
				t.Fatalf("the projection lost provenance.%s", key)
			}
			if index < previous {
				t.Fatalf("the projected provenance key %s is out of order", key)
			}
			previous = index
		}
		if strings.Contains(tail, `"version"`) {
			t.Fatal("the projected ruleset must drop its operational version")
		}
	})

	t.Run("exclusions", func(t *testing.T) {
		for _, excluded := range []string{"collector_version", "parser_version", "argv_sanitized", "started_at", "ended_at", "budget"} {
			if strings.Contains(projection, excluded) {
				t.Fatalf("the projection leaks the excluded metadata %s", excluded)
			}
			if !strings.Contains(envelope, excluded) {
				t.Fatalf("the envelope must carry the excluded metadata %s", excluded)
			}
		}
	})

	t.Run("hash preimage and shape", func(t *testing.T) {
		hash := hashOf(t, bundle)
		if !regexp.MustCompile(`^sha256:[0-9a-f]{64}$`).MatchString(hash) {
			t.Fatalf("the digest does not follow sha256:<64 lowercase hex>: %s", hash)
		}
		digest := sha256.Sum256([]byte(projection))
		if expected := "sha256:" + hex.EncodeToString(digest[:]); expected != hash {
			t.Fatalf("the digest does not cover the projection bytes: %s", expected)
		}
		if strings.Contains(envelope, hash) || strings.Contains(projection, hash) {
			t.Fatal("the digest must not be embedded in the documents")
		}
	})

	t.Run("canonicalization", func(t *testing.T) {
		if encoded := canonicalEnvelope(t, bundle); encoded[0] != '{' || encoded[len(encoded)-1] != '}' {
			t.Fatalf("the envelope is not a single JSON object: %q", encoded)
		}
		if strings.HasPrefix(envelope, "\ufeff") {
			t.Fatal("the canonical bytes must not carry a BOM")
		}
		if strings.HasSuffix(envelope, "\n") || strings.HasSuffix(projection, "\n") {
			t.Fatal("the canonical bytes must not carry a trailing newline")
		}
		if strings.ContainsAny(envelope, "\n\r\t") {
			t.Fatal("the canonical bytes must not contain whitespace outside tokens")
		}
	})

	t.Run("completeness", func(t *testing.T) {
		partial := testGoldenV02Bundle(t)
		// The reviewed vector inventories a regular and an init image; dropping
		// the ephemeral class makes the observation partial.
		partial.ObservedContainerClasses = []contract.ContainerClass{contract.ContainerInit, contract.ContainerRegular}
		partial.Provenance.Completeness = contract.CompletenessPartial
		partial.Provenance.Errors = []string{"ephemeral containers were not observed"}
		if _, err := CanonicalJSON(partial); err != nil {
			t.Fatalf("a partial 0.2 observation must canonicalize: %v", err)
		}
		partial.Provenance.Completeness = contract.CompletenessComplete
		if _, err := CanonicalJSON(partial); err == nil {
			t.Fatal("promoting a partial capture to complete was accepted in 0.2")
		}
	})

	t.Run("warnings", func(t *testing.T) {
		warned := testGoldenV02Bundle(t)
		warned.Evidence[1].Warnings = []contract.Warning{{
			Code: "future_code", Class: contract.WarningInformational, Message: "uninterpretable by this version",
		}}
		if _, err := CanonicalJSON(warned); err != nil {
			t.Fatalf("an unknown warning code must be preserved in 0.2: %v", err)
		}
		if warned.Evidence[1].Warnings[0].CodeKnown() {
			t.Fatal("the 0.2 code set must not claim to know a future warning code")
		}
		if !(contract.Warning{Code: "uid_changed", Class: contract.WarningContradictory, Message: "uid changed"}).CodeKnown() {
			t.Fatal("uid_changed is part of the code set kept by 0.2")
		}
	})
}
